-- Crons chamam as rotinas de sincronização com o token interno (as functions passaram a exigir).
select cron.schedule('bodyoga-pagarme-sync', '*/10 * * * *', $$ select net.http_post(url := 'https://rjksutoohsvwqnqlemjv.supabase.co/functions/v1/pagarme-sync', headers := jsonb_build_object('Content-Type','application/json','x-internal-token',(select value from public.app_settings where key='awise_webhook_token')), body := '{}'::jsonb, timeout_milliseconds := 30000) $$);
select cron.schedule('bodyoga-me-sync-tracking', '17 */2 * * *', $$ select net.http_post(url := 'https://rjksutoohsvwqnqlemjv.supabase.co/functions/v1/me-sync-tracking', headers := jsonb_build_object('Content-Type','application/json','x-internal-token',(select value from public.app_settings where key='awise_webhook_token')), body := '{}'::jsonb, timeout_milliseconds := 30000) $$);
select cron.schedule('bodyoga-fin-pagarme-sync', '23 9 * * *', $$ select net.http_post(url := 'https://rjksutoohsvwqnqlemjv.supabase.co/functions/v1/fin-pagarme-sync', headers := jsonb_build_object('Content-Type','application/json','x-internal-token',(select value from public.app_settings where key='awise_webhook_token')), body := '{}'::jsonb, timeout_milliseconds := 60000) $$);
